def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    my = [h[0] for h in history]
    op = [h[1] for h in history]

    # If opponent has always defected, defect forever
    if all(o == 'D' for o in op):
        return 'D'

    # Initial cooperation and probe
    if n < 10:
        return 'C'
    if n == 10:
        return 'D'
    if n == 11:
        return 'C'

    # After probe
    if n == 99:
        return 'D'
    if n == 12:
        return 'C'

    last_my, last_op = history[-1]
    if last_op == 'D':
        if last_my == 'D':
            return 'C'
        return 'D'
    else:
        # Opponent cooperated. If they tolerated our probe, defect on schedule.
        if history[11][1] == 'C':
            my_defects = sum(1 for a in my if a == 'D')
            if my_defects < n // 10:
                return 'D'
        return 'C'
